function out(string $msg, string $type = 'info'): void {
    $colors = ['info' => '#0ea5e9', 'ok' => '#22c55e', 'warn' => '#f59e0b', 'err' => '#ef4444', 'head' => '#a855f7'];
    $c = $colors[$type] ?? '#94a3b8';
    echo "<div style='font-family:monospace;padding:2px 0;color:{$c}'>{$msg}</div>";
    ob_flush();
    flush();
}

function outHead(string $msg): void {
    echo "<h3 style='color:#a855f7;font-family:monospace;margin-top:16px'>▶ {$msg}</h3>";
    ob_flush(); flush();
}

