// ─── cURL helper ───────────────────────────────────────────────────
$cookieFile = sys_get_temp_dir() . '/dlhs_scraper_cookies.txt';

function dlhsGet(string $url, array $postData = []): string {
    global $cookieFile;
    $ch = curl_init();
    curl_setopt_array($ch, [
        CURLOPT_URL            => $url,
        CURLOPT_RETURNTRANSFER => true,
        CURLOPT_FOLLOWLOCATION => true,
        CURLOPT_COOKIEFILE     => $cookieFile,
        CURLOPT_COOKIEJAR      => $cookieFile,
        CURLOPT_TIMEOUT        => 60,
        CURLOPT_SSL_VERIFYPEER => false,
        CURLOPT_USERAGENT      => 'Mozilla/5.0 (Macintosh; Intel Mac OS X 10_15_7) Chrome/120',
        CURLOPT_HTTPHEADER     => ['Referer: ' . PORTAL_BASE . '/login.php'],
    ]);
    if ($postData) {
        curl_setopt($ch, CURLOPT_POST, true);
        curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query($postData));
    }
    $resp = curl_exec($ch);
    $err  = curl_error($ch);
    curl_close($ch);
    if ($err) throw new RuntimeException("cURL error: $err");
    return $resp ?: '';
}

// ─── HTML table parser ──────────────────────────────────────────────
function parseTable(string $html, bool $firstRowIsHeader = true): array {
    $rows = [];
    // Strip scripts and styles
    $html = preg_replace('/<script[\s\S]*?<\/script>/i', '', $html);
    $html = preg_replace('/<style[\s\S]*?<\/style>/i',   '', $html);

    preg_match_all('/<tr[^>]*>([\s\S]*?)<\/tr>/i', $html, $trMatches);
    foreach ($trMatches[1] as $tr) {
        preg_match_all('/<t[dh][^>]*>([\s\S]*?)<\/t[dh]>/i', $tr, $tdMatches);
        $row = [];
        foreach ($tdMatches[1] as $td) {
            $cell = strip_tags(html_entity_decode($td, ENT_QUOTES | ENT_HTML5, 'UTF-8'));
            $cell = preg_replace('/\s+/', ' ', trim($cell));
            $row[] = $cell;
        }
        if (array_filter($row)) {
            $rows[] = $row;
        }
    }
    return $rows;
}

// Extract <option value="X"> Text </option> pairs
function parseOptions(string $html, string $selectName): array {
    $opts = [];
    if (preg_match('/<select[^>]+name=["\']?' . preg_quote($selectName, '/') . '["\']?[^>]*>([\s\S]*?)<\/select>/i', $html, $m)) {
        preg_match_all('/<option[^>]+value=["\']?(\d+)["\']?[^>]*>([\s\S]*?)<\/option>/i', $m[1], $matches, PREG_SET_ORDER);
        foreach ($matches as $match) {
            $opts[intval($match[1])] = trim(strip_tags($match[2]));
        }
    }
    return $opts;
}

