    // Detect section/department from class name
    $upper = strtoupper($className);
    if (str_contains($upper, 'BASIC 7') || str_contains($upper, 'BASIC 8') || str_contains($upper, 'BASIC 9')) {
        $section = 'Junior';
        $dept = 'General';
    } elseif (str_contains($upper, 'SCIENCE')) {
        $section = 'Senior';
        $dept = 'Science';
    } elseif (str_contains($upper, 'HUM') || str_contains($upper, 'HUMANITIES') || str_contains($upper, 'ARTS') || str_contains($upper, 'COMMERCE')) {
        $section = 'Senior';
        $dept = 'Humanities';
    } elseif (str_contains($upper, 'CLASS OF')) {
        $section = 'Alumni';
        $dept = str_contains($upper, 'HUM') ? 'Humanities' : 'Science';
    } else {
        $section = 'Other';
        $dept = 'General';
    }

    $classes[$classId] = [
        'portal_id' => $classId,
        'name'      => $className,
        'section'   => $section,
        'dept'      => $dept,
    ];

