    // Pattern: each student result is a card/div with name, subject scores
    // Try to find admission numbers and names
    preg_match_all('/Admission\s*(?:No|Number)[:\s]*([A-Z0-9\/-]+)/i', $html, $admMatches);
    preg_match_all('/Student\s*Name[:\s]*([A-Z][A-Z\s]+)/i', $html, $nameMatches);

    // Extract score tables
    $rows = parseTable($html);
    $currentStudent = null;
    $subjectRows = [];

    foreach ($rows as $row) {
        $r0 = trim($row[0] ?? '');
        $r1 = trim($row[1] ?? '');

        // Detect student name row (all caps, no numbers)
        if (preg_match('/^[A-Z][A-Z\s]{5,50}$/', $r0) && empty($r1)) {
            if ($currentStudent && $subjectRows) {
                $parsedStudentResults[] = array_merge($batch, [
                    'student_name' => $currentStudent,
                    'scores'       => $subjectRows,
                    'html'         => null,
                ]);
            }
            $currentStudent = $r0;
            $subjectRows = [];
        } elseif ($currentStudent && count($row) >= 3 && is_numeric($row[count($row)-1])) {
            // Score row: subject name + scores
            $subjectRows[] = $row;
        }
    }

    // Flush last student
    if ($currentStudent && $subjectRows) {
        $parsedStudentResults[] = array_merge($batch, [
            'student_name' => $currentStudent,
            'scores'       => $subjectRows,
            'html'         => null,
        ]);
    }
}

