// STEP 10 — GENERATE SUMMARY REPORT
// =====================================================================
outHead('Step 10 — Extraction Summary');

$summary = [
    'extracted_at'       => date('Y-m-d H:i:s'),
    'portal'             => 'dlhsportal.org',
    'classes'            => count($classes),
    'sessions'           => $sessions,
    'subjects'           => count($subjects),
    'broadsheets'        => count($broadsheets),
    'student_results'    => count($parsedStudentResults),
    'ehi_winifred'       => $ehiFound,
    'files_generated'    => array_map('basename', glob(EXTRACT_DIR . '/*')),
];

file_put_contents(EXTRACT_DIR . '/summary.json', json_encode($summary, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE));

out('', 'info');
out('═══════════════════════════════════════════════', 'ok');
out('✅ EXTRACTION COMPLETE', 'ok');
out("   Classes extracted   : {$summary['classes']}", 'ok');
out("   Subjects extracted  : {$summary['subjects']}", 'ok');
out("   Broadsheets fetched : {$summary['broadsheets']}", 'ok');
out("   Student result sets : {$summary['student_results']}", 'ok');
out('═══════════════════════════════════════════════', 'ok');
out('', 'info');
out('📁 All files saved to: database/portal_extract/', 'ok');
out('', 'info');
out('➡️  Next step: Run <a href="portal_importer.php" style="color:#38bdf8">portal_importer.php</a> to import into Aroura LMS', 'ok');

// =====================================================================
// STEP 11 — OPTIONAL AUTO-IMPORT
// =====================================================================
if (IMPORT_DB && isset($_GET['import']) && $_GET['import'] === 'now') {
    outHead('Step 11 — Importing into Aroura LMS Database');
    // Import will be done by portal_importer.php
    out('  Run portal_importer.php separately for full control', 'warn');
}

